# remove obvious parse glitch if any
hier={h for h in hier if h"'!='"'is'}

def mask_comments_strings(s):
  out=list(s); i=0; n=len(s)
  while i<n:
    if s.startswith('//',i):
      j=s.find('\\n',i); j=n if j<0 else j
      for k in range(i,j): out[k]=' '
      i=j
    elif s.startswith('/*',i):
      j=s.find('*/',i+2); j=n-2 if j<0 else j
      for k in range(i,j+2): out[k]=' '
      i=j+2
    elif s[i] in ('\"',\"'\"):
      q=s[i]; out[i]=' '; i+=1
      while i<n:
        if s[i]=='\\\\': out[i]=' '; i+=1; 
        if i<n: out[i]=' '
        if i<n and s[i]==q:
          i+=1; break
        i+=1
    else: i+=1
  return ''.join(out)

def line_starts(s):
  starts=[0]
  for m in re.finditer('\\n',s): starts.append(m.end())
  return starts

def line_no(starts,pos): return bisect.bisect_right(starts,pos)

def find_matching(clean,openpos):
  depth=0
  for i in range(openpos,len(clean)):
    c=clean[i]
    if c=='{': depth+=1
    elif c=='}':
      depth-=1
      if depth==0: return i
  return len(clean)

def scope_intervals(path,clean):
  intervals=[]
  # named class scopes
  for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', clean):
    name=m.group(1); header=m.group(2); ext=None
    em=re.search(r'\\bextends\\s+([\\w\\.]+)', header)
    if em: ext=em.group(1).split('.')[-1]
    if name in hier or ext in hier:
      openpos=clean.find('{',m.start(),m.end())
      intervals.append((openpos,find_matching(clean,openpos),name))
