  for m in re.finditer(r'new\\s+(\\w+)\\b["'^;{}]*'"\\{', clean):
    typ=m.group(1)
    if typ in hier:
      openpos=clean.find('{',m.start(),m.end())
      intervals.append((openpos,find_matching(clean,openpos),'anon'))
  return intervals

def in_intervals(intervals,pos):
  return any(a<=pos<=b for a,b,_ in intervals)

method_decl_re=re.compile(r'(?:(?:public|protected|private|static|final|abstract|synchronized|native|strictfp|default)\\s+)*(?:<["'^;{}()]+>'"\\s*)?[\\w@?\\[\\]<>.,\\s]+\\s+(\\w+)\\s*\\(["'^;{}]*'"\\)\\s*(?:throws\\s+[\\w\\s,<>.]+)?\\s*(?:\\{|;)')

def method_name_at(clean,pos):
  # if occurrence in method declaration itself
  line_start=clean.rfind('\\n',0,pos)+1; line_end=clean.find('\\n',pos); line_end=len(clean) if line_end<0 else line_end
  line=clean[line_start:line_end]
  mm=method_decl_re.search(line)
  if mm and ' delegate' in line: return mm.group(1)
  # scan backwards up to 5000 chars for last method header whose body contains pos
  start=max(0,pos-8000); region=clean[start:pos+1]
  candidates=[]
  for mm in method_decl_re.finditer(region):
    abs_start=start+mm.start(); abs_end=start+mm.end()
    if clean[abs_end-1]=='{':
      end=find_matching(clean,abs_end-1)
      if abs_end-1 <= pos <= end:
        candidates.append((abs_start,mm.group(1)))
  if candidates:
    return candidates[-1][1]
  return None

sites=[]; details=[]
for path,txt in texts.items():
  clean=mask_comments_strings(txt)
  intervals=scope_intervals(path,clean)
  if not intervals: continue
  starts=line_starts(txt)
  for m in re.finditer(r'\\bdelegate\\s*\\(', clean):
    if not in_intervals(intervals,m.start()): continue
    name=method_name_at(clean,m.start()) or '<unknown>'
    sites.append(f'{path}:{name}')
    details.append((path,line_no(starts,m.start()),name,txt[txt.rfind('\\n',0,m.start())+1:txt.find('\\n',m.start()) if txt.find('\\n',m.start())"'!=-1 else len(txt)].strip()))
for d in sorted(details):
  print('"'%s:%s:%s: %s'%d)
print('---SITES---')
for s in sorted(set(sites)):
  print(s)
print('count',len(set(sites)))
