   for k in range(i,j): out[k]=' '
   i=j
  elif s.startswith('/*',i):
   j=s.find('*/',i+2); j=n-2 if j<0 else j
   for k in range(i,j+2): out[k]=' '
   i=j+2
  elif s[i] in ('\"',\"'\"):
   q=s[i]; out[i]=' '; i+=1; esc=False
   while i<n:
    ch=s[i]; out[i]=' '
    if esc: esc=False
    elif ch=='\\\\': esc=True
    elif ch==q: i+=1; break
    i+=1
  else: i+=1
 return ''.join(out)
