  classes.append((m.group(1),ext,p))
hier={'ForwardingObject'}; ch=True
while ch:
 ch=False
 for name,ext,p in classes:
  if ext in hier and name not in hier:
   hier.add(name); ch=True
hier.discard('is')

def match(c,op):
 d=0
 for i in range(op,len(c)):
  if c[i]=='{': d+=1
  elif c[i]=='}':
   d-=1
   if d==0: return i
 return len(c)-1

def affected_scopes(c):
 scopes=[]
 for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', c):
  name=m.group(1); em=re.search(r'\\bextends\\s+([\\w\\.]+)',m.group(2)); ext=em.group(1).split('.')[-1] if em else None
  if name in hier or ext in hier:
   op=c.find('{',m.start(),m.end()); scopes.append((op,match(c,op),name))
 for m in re.finditer(r'new\\s+(\\w+)\\b["'^;{}]*'"\\{', c):
  if m.group(1) in hier:
   op=c.find('{',m.start(),m.end()); scopes.append((op,match(c,op),'anon'))
 return scopes
control={'if','for','while','switch','catch','synchronized','try','else','do','return','new'}

def method_name_from_header(h):
 hs=' '.join(h.strip().split())
