 # reject class/anon/array init
 if re.search(r'\\b(class|interface|enum)\\b',hs): return None
 pm=hs.rfind(')')
 if pm<0: return None
 lp=hs.rfind('(',0,pm)
 if lp<0: return None
 before=hs[:lp].strip()
 toks=re.findall(r'[A-Za-z_"'$]['"\\w"'$]*'"',before)
 if not toks: return None
 name=toks[-1]
 if name in control: return None
 # constructor possible; but no delegate calls in constructors likely
 return name

def method_intervals(c):
 intervals=[]
 for i,ch in enumerate(c):
  if ch=='{':
   j=max(c.rfind(';',0,i),c.rfind('{',0,i),c.rfind('}',0,i))
   h=c[j+1:i]
   name=method_name_from_header(h)
   if name:
    intervals.append((i,match(c,i),name))
 return intervals

def enclosing_method(methods,pos):
 cand=[(a,b,n) for a,b,n in methods if a<=pos<=b]
 if cand: return max(cand,key=lambda x:x[0])[2]
 # abstract/interface method declaration line
 return method_name_from_header(cleans_cur[cleans_cur.rfind('\\n',0,pos)+1: (cleans_cur.find('\\n',pos) if cleans_cur.find('\\n',pos)>=0 else len(cleans_cur))])

sites=set(); details=[]
for p,c in cleans.items():
 scopes=affected_scopes(c)
 if not scopes: continue
 methods=method_intervals(c)
 starts=[0]+[m.end() for m in re.finditer('\\n',c)]
 def inscope(pos): return any(a<=pos<=b for a,b,_ in scopes)
 cleans_cur=c
 for m in re.finditer(r'\\bdelegate\\s*\\(', c):
  if not inscope(m.start()): continue
  mn=enclosing_method(methods,m.start())
  if not mn: mn='<unknown>'
  sites.add(f'{p}:{mn}')
  line=bisect.bisect_right(starts,m.start())
  details.append((p,line,mn,texts[p][texts[p].rfind('\\n',0,m.start())+1:texts[p].find('\\n',m.start()) if texts[p].find('\\n',m.start())"'!=-1 else len(texts[p])].strip()))
for d in sorted(details): print('"'%s:%s:%s: %s'%d)
print('---SITES---')
for s in sorted(sites): print(s)
print('count',len(sites))
