# Same parser, output JSON sites only; reject anonymous headers as methods.
import os,re,bisect,json
root='src'
texts={}
for dp,_,fs in os.walk(root):
 for fn in fs:
  if fn.endswith('.java'):
   p=os.path.join(dp,fn); texts[p]=open(p).read()
def mask(s):
 out=list(s); i=0; n=len(s)
 while i<n:
  if s.startswith('//',i):
   j=s.find('\\n',i); j=n if j<0 else j
   for k in range(i,j): out[k]=' '
   i=j
  elif s.startswith('/*',i):
   j=s.find('*/',i+2); j=n-2 if j<0 else j
   for k in range(i,j+2): out[k]=' '
   i=j+2
  elif s[i] in ('\"',\"'\"):
   q=s[i]; out[i]=' '; i+=1; esc=False
   while i<n:
    ch=s[i]; out[i]=' '
    if esc: esc=False
    elif ch=='\\\\': esc=True
    elif ch==q: i+=1; break
    i+=1
  else: i+=1
 return ''.join(out)
cleans={p:mask(s) for p,s in texts.items()}
classes=[]
for p,c in cleans.items():
 for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', c):
  em=re.search(r'\\bextends\\s+([\\w\\.]+)',m.group(2)); ext=em.group(1).split('.')[-1] if em else None
  classes.append((m.group(1),ext,p))
hier={'ForwardingObject'}; changed=True
while changed:
 changed=False
 for n,e,p in classes:
  if e in hier and n not in hier:
   hier.add(n); changed=True
hier.discard('is')
def match(c,op):
 d=0
 for i in range(op,len(c)):
  if c[i]=='{': d+=1
  elif c[i]=='}':
   d-=1
   if d==0: return i
 return len(c)-1
def scopes(c):
 res=[]
 for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', c):
  n=m.group(1); em=re.search(r'\\bextends\\s+([\\w\\.]+)',m.group(2)); e=em.group(1).split('.')[-1] if em else None
  if n in hier or e in hier:
   op=c.find('{',m.start(),m.end()); res.append((op,match(c,op)))
 for m in re.finditer(r'new\\s+(\\w+)\\b["'^;{}]*'"\\{', c):
  if m.group(1) in hier:
   op=c.find('{',m.start(),m.end()); res.append((op,match(c,op)))
 return res
control={'if','for','while','switch','catch','synchronized','try','else','do','return','new'}
def method_name(h):
 hs=' '.join(h.strip().split())
 if not hs or '=' in hs or hs.startswith('new ') or ' new ' in hs: return None
 if re.search(r'\\b(class|interface|enum)\\b',hs): return None
 pm=hs.rfind(')'); lp=hs.rfind('(',0,pm)
 if pm<0 or lp<0: return None
 before=hs[:lp].strip()
 toks=re.findall(r'[A-Za-z_"'$]['"\\w"'$]*'"',before)
 if not toks: return None
 name=toks[-1]
 if name in control: return None
 return name
def methods(c):
 res=[]
 for i,ch in enumerate(c):
  if ch=='{':
   j=max(c.rfind(';',0,i),c.rfind('{',0,i),c.rfind('}',0,i))
   n=method_name(c[j+1:i])
   if n: res.append((i,match(c,i),n))
 return res
def encl(c,ms,pos):
 cand=[x for x in ms if x[0]<=pos<=x[1]]
 if cand: return max(cand,key=lambda x:x[0])[2]
 ls=c.rfind('\\n',0,pos)+1; le=c.find('\\n',pos); le=len(c) if le<0 else le
 return method_name(c[ls:le])
sites=set(); unknown=[]
for p,c in cleans.items():
 sc=scopes(c)
 if not sc: continue
 ms=methods(c)
 for m in re.finditer(r'\\bdelegate\\s*\\(',c):
  if not any(a<=m.start()<=b for a,b in sc): continue
  n=encl(c,ms,m.start())
  if not n: unknown.append((p,m.start())); continue
  sites.add(f'{p}:{n}')
print(json.dumps(sorted(sites),indent=2))
print('count',len(sites),'unknown',len(unknown), file=os.sys.stderr)
if unknown[:5]: print(unknown[:5], file=os.sys.stderr)
